<?php

namespace App\Services;

use App\Models\ReconciliationBatch;
use App\Models\ReconciliationEntry;
use Carbon\CarbonImmutable;

/**
 * Deterministic, read-only finance investigation.
 * No SQL generated by AI, no external transfers of individual transaction data.
 */
class FinanceAiAudit
{
    public function __construct(private FinanceAiContext $context) {}

    public function investigate(string $month, ?string $accountCode = null, ?float $minimum = null): array
    {
        $period = $this->period($month);
        $query = $this->context->expenseQuery($period[0], $period[1]);

        if ($accountCode !== null && $accountCode !== '') {
            if (!preg_match('/^[0-9A-Za-z._-]{1,30}$/D', $accountCode)) {
                throw new \InvalidArgumentException('Kode akun tidak valid.');
            }
            $query->where('account_code', $accountCode);
        }
        if ($minimum !== null && $minimum > 0) {
            $query->where('debit', '>=', $minimum);
        }

        $total = (float)(clone $query)->sum('debit');
        $count = (int)(clone $query)->count();
        $rows = $query->orderByDesc('debit')->orderBy('id')->limit(50)
            ->get(['id', 'transaction_date', 'account_code', 'account_name', 'description', 'debit'])
            ->map(fn ($r) => [
                'id'=>$r->id,
                'date'=>$r->transaction_date->format('d/m/Y'),
                'code'=>$r->account_code,
                'account'=>$r->account_name,
                'description'=>$r->description ?: '—',
                'amount'=>(float)$r->debit,
            ])->all();

        return ['count'=>$count,'total'=>$total,'rows'=>$rows, 'limited'=>$count > 50];
    }

    public function anomalies(string $month): array
    {
        [$start,$end] = $this->period($month);
        $query = $this->context->expenseQuery($start,$end);
        // Pull only bounded aggregate candidates; no full table scan into memory.
        $duplicates = (clone $query)
            ->selectRaw('account_code, transaction_date, debit, COUNT(*) as occurrences')
            ->groupBy('account_code','transaction_date','debit')
            ->havingRaw('COUNT(*) > 1')
            ->orderByDesc('occurrences')
            ->limit(20)->get()
            ->map(fn ($r) => [
                'kind'=>'potential_duplicate',
                'label'=>'Potensi duplikat',
                'message'=>'Akun '.$r->account_code.' · '.$r->transaction_date.' · Rp '.number_format((float)$r->debit,0,',','.').' · '.$r->occurrences.' transaksi dengan tanggal & nominal sama',
                'count'=>(int)$r->occurrences,
            ])->all();

        $totals = (clone $query)->selectRaw('account_code, COUNT(*) as items, AVG(debit) as average_amount')
            ->groupBy('account_code')->get()->keyBy('account_code');
        // Simple and explainable outlier rule: 3x average, at least Rp 1m and
        // only accounts with 5+ transactions. Signals, not fraud findings.
        $unusual = [];
        foreach ($totals as $account => $stat) {
            if ((int)$stat->items < 5 || (float)$stat->average_amount <= 0) continue;
            $threshold = max(1000000, (float)$stat->average_amount * 3);
            foreach ((clone $query)->where('account_code',$account)
                ->where('debit','>=',$threshold)->orderByDesc('debit')->limit(3)
                ->get(['transaction_date','debit']) as $row) {
                $unusual[] = [
                    'kind'=>'high_amount',
                    'label'=>'Nominal tidak biasa',
                    'message'=>'Akun '.$account.' · '.$row->transaction_date->format('d/m/Y')
                        .' · Rp '.number_format((float)$row->debit,0,',','.')
                        .' (minimal 3× rata-rata akun)',
                    'count'=>1,
                ];
            }
        }
        return array_slice(array_merge($duplicates,$unusual),0,30);
    }

    public function reconciliation(int $userId, string $month): array
    {
        [$start,$end] = $this->period($month);
        $batches = ReconciliationBatch::query()->where('user_id',$userId)
            ->whereHas('entries',fn ($q) => $q->whereBetween('posted_at',[$start,$end]))
            ->orderByDesc('id')->limit(15)->get();
        $out = [];
        foreach ($batches as $batch) {
            $bank = $batch->entries()->where('source','bank')->whereBetween('posted_at',[$start,$end]);
            $ledger = $batch->entries()->where('source','ledger')->whereBetween('posted_at',[$start,$end]);
            $unmatchedBank = (clone $bank)->where('status','unmatched');
            $unmatchedLedger = (clone $ledger)->where('status','unmatched');
            $out[] = [
                'id'=>$batch->id,
                'label'=>$batch->name,
                'bank'=>$batch->bank_name,
                'bank_total'=>(int)(clone $bank)->count(),
                'matched'=>(int)(clone $bank)->where('status','matched')->count(),
                'suggested'=>(int)(clone $bank)->where('status','suggested')->count(),
                'unmatched_bank'=>(int)$unmatchedBank->count(),
                'unmatched_bank_total'=>(float)(clone $unmatchedBank)->sum('amount'),
                'unmatched_ledger'=>(int)$unmatchedLedger->count(),
                'unmatched_ledger_total'=>(float)(clone $unmatchedLedger)->sum('amount'),
            ];
        }
        return $out;
    }

    public function snapshot(int $userId, string $month): array
    {
        $dashboard = $this->context->dashboard($month);
        return [
            'period'=>$month,
            'generated_at'=>now()->toIso8601String(),
            'expenses'=>$dashboard['total'],
            'previous_expenses'=>$dashboard['previous_total'],
            'change'=>$dashboard['delta'],
            'monthly_chart'=>$dashboard['chart'],
            'accounts'=>$dashboard['accounts'],
            'insights'=>$dashboard['insights'],
            'anomaly_signals'=>$this->anomalies($month),
            'reconciliation'=>$this->reconciliation($userId,$month),
            'disclaimer'=>'Snapshot angka internal. Anomali adalah indikasi untuk diperiksa, bukan bukti kesalahan. Pasangan suggested belum disetujui.',
        ];
    }

    private function period(string $month): array
    {
        $period = CarbonImmutable::createFromFormat('!Y-m',$month);
        if (!$period || $period->format('Y-m') !== $month) {
            throw new \InvalidArgumentException('Format periode tidak valid.');
        }
        return [$period->startOfMonth()->toDateString(),$period->endOfMonth()->toDateString()];
    }
}
